(() => {
 const data=window.NEMO_CONTENT;if(!data)return;const params=new URLSearchParams(location.search),type=document.body.dataset.page;
 if(type==='portfolio'){const p=data.projects.find(p=>p.id===params.get('project'));if(p?.isActual){const meta=document.querySelector('.detail-intro>.page-meta');if(meta)meta.textContent=p.category+' · '+p.style+' · 프로젝트';}const title=document.querySelector('.detail-intro h1');if(title)document.title=title.textContent+' — NEMO';}
 if(type==='story'){const p=data.stories.find(p=>p.id===params.get('article'))||(!params.has('article')?data.stories[0]:null);if(p){const makeImage=src=>{const image=document.createElement('img');image.src=src;image.alt='';image.loading='lazy';image.className='cms-article-image';return image;};document.querySelectorAll('.article-body>section').forEach((section,i)=>{const src=p.sections[i]?.[2];if(src?.startsWith('/media/'))section.append(makeImage(src));});const used=new Set([p.visual,...p.sections.map(s=>s[2])]);for(const src of(p.images||[]).filter(src=>src.startsWith('/media/')&&!used.has(src)))document.querySelector('.article-end')?.before(makeImage(src));}const title=document.querySelector('.article-header h1');if(title)document.title=title.textContent+' — NEMO';}
})();
